-- Generated by quack_to_fastapi.sql from quackapi route example_orders: its handler, unchanged but for
-- renamed catalogs, returning the response body as one BLOB.
WITH route_rows AS (
WITH order_lines AS (SELECT l.order_id, list ({ 'sku' : l.sku, 'quantity' : l.quantity, 'unit_price' : l.unit_price } ORDER BY l.sku) AS lines FROM main.example_order_lines AS l GROUP BY l.order_id) SELECT o.id, o.status, o.total, o.placed_at, o.note, coalesce (ol.lines, []) AS lines FROM main.example_orders AS o LEFT JOIN order_lines AS ol ON ol.order_id = o.id WHERE o.customer_id = $customer_id::UUID AND o.placed_at >= $since::DATE ORDER BY o.placed_at
)
SELECT encode(to_json(coalesce(list(route_rows), []))::VARCHAR) FROM route_rows;
